try {
  const mission = $json.mission?.body || $json.mission || $json;
  const report = mission.report_text || 'Rapport disponible via le lien sécurisé.';
  const summary = report.replace(/[#*_`>]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 850);
  const chatId = String(mission.telegram_chat_id || $json.telegram_chat_id || '8878273150');
  const pdfBase64 = mission.pdf_base64 || $json.pdf_base64 || '';
  const pdfUrl = mission.pdf_url || mission.webViewLink || '';
  const hasBinary = typeof $binary !== 'undefined' && $binary && Object.keys($binary).length > 0;

  if (!pdfUrl && !pdfBase64 && !hasBinary) {
    throw new Error('URL ou fichier binaire du rapport PDF manquant.');
  }

  const fileName = `${mission.reference_mission || mission.Code_Mission || 'Rapport_Audit_eMETA'}.pdf`;
  const binaryOutput = pdfBase64
    ? { data: { data: pdfBase64, mimeType: 'application/pdf', fileName } }
    : (hasBinary ? $binary : undefined);

  return [{
    json: {
      ...mission,
      summary,
      pdf_url: pdfUrl,
      telegram_chat_id: chatId
    },
    ...(binaryOutput ? { binary: binaryOutput } : {})
  }];
} catch (err) {
  throw new Error(`Préparation Desk impossible: ${err.message}`);
}

try {
  const context = $('Préparer synthèse Desk').first().json;
  return [{ json: { ...context, telegram_response: $input.first().json } }];
} catch (err) { throw new Error(`Conservation du contexte HITL impossible: ${err.message}`); }

