={{
  {
    contents: [
      {
        parts: [
          {
            text: "Tu es l'auditeur qualité senior d'e-META LABS. Évalue ce rapport d'audit stratégique. Vérifie qu'il est complet, structuré sur l'ensemble des chapitres, sans texte tronqué ni erreur manifeste. Réponds UNIQUEMENT en JSON valide avec la structure exacte : {\"action\": \"validate\", \"consignes\": \"\"} si le rapport est conforme, ou {\"action\": \"revise\", \"consignes\": \"<liste précise des corrections à apporter>\"} si une révision est nécessaire.\n\nRAPPORT À AUDITER :\n" + ($('Préparer synthèse Desk').first().json.report_text || '')
          }
        ]
      }
    ],
    generationConfig: {
      temperature: 0.1,
      responseMimeType: "application/json"
    }
  }
}}

={{
  (() => {
    const safeFirst = (name) => {
      try { return $(name).first()?.json || {}; } catch (_) { return {}; }
    };

    const rawWebhook = safeFirst('Webhook Rapport');
    const webhookBody = (rawWebhook.body && typeof rawWebhook.body === 'object') ? rawWebhook.body : rawWebhook;
    const initData = safeFirst('Initialisation standardisée');
    const initialCtx = safeFirst('Conserver contexte initial HITL');
    const revisedCtx = safeFirst('Conserver contexte révisé');

    const merged = {
      ...webhookBody,
      ...initData,
      ...initialCtx,
      ...revisedCtx
    };

    const ref = String(
      merged.reference_mission ||
      merged.mission_ref ||
      merged.Mission_Ref ||
      merged.reference ||
      webhookBody.reference_mission ||
      webhookBody.mission_ref ||
      ''
    ).trim();

    return {
      ...merged,
      reference_mission: ref,
      mission_ref: ref,
      Mission_Ref: ref,
      whatsapp: merged.whatsapp || merged.telephone || webhookBody.whatsapp || webhookBody.telephone || '',
      telephone: merged.telephone || merged.whatsapp || webhookBody.telephone || webhookBody.whatsapp || '',
      empreinte_sha256: merged.empreinte_sha256 || merged.sha256_hash || webhookBody.empreinte_sha256 || '',
      quality_gate: $json,
              action: 'validate',
        pdf_base64: $('Préparer synthèse Desk').first().json.pdf_base64 || $('Initialisation standardisée').first().json.pdf_base64 || ''
    };
  })()
}}

parameters.jsCode:
try {
  const mission = $('Préparer synthèse Desk').first().json;
  const instructions = String($json.query.instructions || $json.query.consigne || '').trim();
  if (!instructions) throw new Error('Une consigne de révision est obligatoire.');
  return [{ json: { ...mission, revision_instructions: instructions, audit_prompt: `Révise le rapport d’audit ci-dessous en suivant uniquement les consignes, sans inventer de faits. Préserve les 20 chapitres et indique les limites.

Consignes : ${instructions}

Rapport : ${mission.report_text || ''}

Contexte : ${JSON.stringify(mission)}` } }];
} catch (err) { throw new Error(`Capture des consignes impossible: ${err.message}`); }

try {
  const mission = $('Capturer consignes de révision').first().json;
  const response = $input.first().json;
  const report = response.candidates?.[0]?.content?.parts?.[0]?.text;
  if (!report) throw new Error('Gemini n’a retourné aucun rapport révisé.');
  return [{ json: { ...mission, report_text: report } }];
} catch (err) { throw new Error(`Mapping rapport révisé impossible: ${err.message}`); }

try {
  const mission = $('Préparer contenu révisé').first().json;
  const result = $input.first().json;
  const link = result.webViewLink || result.url;
  if (!link) throw new Error('Le moteur PDF n’a retourné aucun lien de consultation.');
  const summary = mission.report_text.replace(/[#*_`>]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 850);
  return [{ json: { ...mission, pdf_url: link, webViewLink: link, summary } }];
} catch (err) { throw new Error(`Mapping PDF révisé impossible: ${err.message}`); }

try {
  const context = $('Préparer renvoi Telegram révisé').first().json;
  return [{ json: { ...context, telegram_response: $input.first().json } }];
} catch (err) { throw new Error(`Conservation du contexte révisé impossible: ${err.message}`); }
